//! Replays workflows_ts_vectors.json (outcomes of the real flag-off workflow
//! services, regenerated by workWorkflowVectors.test.ts) through the Rust `workflow*` ops.
use serde_json::{Map, Value, json};

use super::run_json;

fn vectors() -> Value {
    serde_json::from_str(include_str!("workflows_ts_vectors.json")).expect("vectors parse")
}

fn run(op: &str, input: &str, name: &Value) -> Value {
    let output = run_json(op, input).unwrap_or_else(|e| panic!("{op} {name}: {e}"));
    serde_json::from_str(&output).expect("output json")
}

#[test]
fn ordered_decisions_equal_typescript_text() {
    let doc = vectors();
    let decisions = doc["decisions"].as_array().expect("decisions");
    assert!(decisions.len() >= 45, "every decision case is recorded");
    for case in decisions {
        let op = case["op"].as_str().expect("op");
        let input = case["input_text"].as_str().expect("input text");
        let output = run_json(op, input).unwrap_or_else(|e| panic!("{op} {}: {e}", case["name"]));
        // Text equality proves the TS key order, not only the values.
        assert_eq!(output, case["expected_text"].as_str().expect("expected text"), "{op}: {}", case["name"]);
    }
}

#[test]
fn paths_equal_typescript() {
    let doc = vectors();
    for case in doc["paths"].as_array().expect("paths") {
        let op = case["op"].as_str().expect("op");
        assert_eq!(run(op, &case["input"].to_string(), &case["name"]), case["expected"], "{op}: {}", case["name"]);
    }
}

#[test]
fn request_bodies_equal_typescript() {
    let doc = vectors();
    let bodies = doc["bodies"].as_array().expect("bodies");
    assert!(bodies.len() >= 15, "every body case is recorded");
    for case in bodies {
        let op = case["op"].as_str().expect("op");
        let out = run(op, &case["input"].to_string(), &case["name"]);
        let expected = &case["expected"];
        if expected.get("error").is_some() {
            assert_eq!(out, *expected, "{op}: {}", case["name"]);
            continue;
        }
        // The page side of buildWorkBody: plain values as is, slots from the page's own values.
        let sent = expected["body"].as_object().expect("sent body");
        let mut body = Map::new();
        let mut names = Vec::new();
        let mut slots = Vec::new();
        for step in out["steps"].as_array().expect("steps") {
            let name = step[0].as_str().expect("step name");
            let value = if let Some(value) = step[1].get("value") {
                value.clone()
            } else {
                let slot = step[1]["slot"].as_str().expect("only value and slot steps");
                slots.push(json!(slot));
                sent.get(slot).cloned().unwrap_or(Value::Null)
            };
            names.push(json!(name));
            body.insert(name.to_owned(), value);
        }
        assert_eq!(Value::Object(body), expected["body"], "body {op}: {}", case["name"]);
        assert_eq!(Value::Array(names), expected["keys"], "key order {op}: {}", case["name"]);
        assert_eq!(Value::Array(slots), case["slots"], "page slots {op}: {}", case["name"]);
        assert_eq!(out["path"], expected["path"], "path {op}: {}", case["name"]);
        assert_eq!(out["method"], expected["method"], "method {op}: {}", case["name"]);
        if let Some(key) = expected.get("idempotency_key") {
            assert_eq!(&out["idempotency_key"], key, "idempotency key {op}: {}", case["name"]);
        }
    }
}

#[test]
fn unknown_ops_and_malformed_inputs_are_refused() {
    assert_eq!(run_json("workflowNothing", "{}").unwrap_err(), "unknown_op:workflowNothing");
    assert_eq!(run_json("workflowTemplatePayload", "{}").unwrap_err(), "missing_field:workflow");
    assert_eq!(run_json("workflowTemplatePayload", r#"{"workflow":{"graph":{"nodes":{}}}}"#).unwrap_err(), "bad_field:workflow.graph.nodes");
    assert_eq!(run_json("workflowPath", r#"{"route":"nope"}"#).unwrap_err(), "bad_field:route");
    assert!(run_json("workflowInputSession", "not json").is_err());
}
